```cpp
class Pet {
public:
    Pet(string n, int a) : name(n), age(a) {}
    string getName() { return name; }
    void   birthday() { age++; }
private:
    string name;
    int    age;
};

int main() {
    Pet cat("奶茶", 2);
    cout << cat.getName();  // ①
    cat.birthday();         // ②
    cat.name = "大橘";      // ③
    cout << cat.getName();  // ④
    return 0;
}
